<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,reactive,ref,watch } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { FileSpreadsheet,Files,HardDrive,Link2,Image as ImageIcon,Video,AudioLines,FileText,Search,RotateCcw,Eye,Trash2,ArrowUpRight,Download,ShieldCheck } from 'lucide-vue-next'
import { request,send } from './api'
import RecordIdentifier from './RecordIdentifier.vue'
const emit=defineEmits<{locate:[reference:any]}>()
const rows=ref<any[]>([]),total=ref(0),page=ref(1),busy=ref(false),error=ref(''),removing=ref('')
const filters=reactive({search:'',kind:'',usage:''}),summary=ref({total:0,used:0,unused:0,bytes:0,unusedBytes:0})
const icons:Record<string,any>={image:ImageIcon,video:Video,audio:AudioLines,handout:FileText,import:FileSpreadsheet}
const names:Record<string,string>={image:'图片',video:'视频',audio:'音频',handout:'附件',import:'导入源文件'}
const ownerNames:Record<string,string>={'learning-answer':'答题记录',product:'商品',message:'消息','message-template':'消息模板',exam:'考试项目',category:'考试分类',course:'课程',knowledge:'知识点',section:'节',chapter:'章',subject:'科目',cheatsheet:'考前小抄',question:'题目',article:'考前须知',faq:'文章',handout:'讲义'}
ownerNames['site-settings']='系统设置';ownerNames['import-job']='导入记录'
const selected=ref<any>(),preview=ref<any>(),previewBusy=ref(false),previewError=ref(''),visible=ref(false)
let revision=0,previewRevision=0,disposed=false
const sizes=(bytes:number)=>{if(bytes<1024)return bytes+' B';if(bytes<1024**2)return (bytes/1024).toFixed(1)+' KB';if(bytes<1024**3)return (bytes/1024**2).toFixed(1)+' MB';return (bytes/1024**3).toFixed(2)+' GB'}
const date=(value:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'未记录'
const extension=(r:any)=>r.filename.split('.').pop()?.toUpperCase()||names[r.kind]
const stats=computed(()=>[{label:'资源总数',value:summary.value.total,unit:'个文件',icon:Files,tone:'blue'},{label:'使用中',value:summary.value.used,unit:'个文件',icon:Link2,tone:'green'},{label:'未引用',value:summary.value.unused,unit:sizes(summary.value.unusedBytes)+' 可清理',icon:ShieldCheck,tone:'amber'},{label:'资源总大小',value:sizes(summary.value.bytes),unit:'上传文件与内嵌图片',icon:HardDrive,tone:'violet'}])
async function load(){const rev=++revision;busy.value=true;error.value='';try{const data=await request('/admin/resources?'+new URLSearchParams({...filters,page:String(page.value)}));if(disposed||rev!==revision)return;rows.value=data.items;total.value=data.total;summary.value=data.summary;if(page.value>1&&!rows.value.length)page.value=Math.max(1,Math.ceil(total.value/20))}catch(e:any){if(rev===revision)error.value=e.message}finally{if(rev===revision)busy.value=false}}
function search(){if(page.value===1)void load();else page.value=1}
function reset(){Object.assign(filters,{search:'',kind:'',usage:''});search()}
watch(page,load)
async function open(row:any){const rev=++previewRevision;selected.value=row;preview.value=null;previewError.value='';visible.value=true;previewBusy.value=true;try{const current=await request('/admin/resources/'+encodeURIComponent(row.id));if(rev!==previewRevision)return;selected.value=current;const result=await send('/admin/resources/'+encodeURIComponent(row.id)+'/preview',{});if(rev===previewRevision)preview.value=result}catch(e:any){if(rev===previewRevision)previewError.value=e.message}finally{if(rev===previewRevision)previewBusy.value=false}}
function close(){previewRevision++;visible.value=false;preview.value=null;selected.value=null}
function locate(reference:any){close();emit('locate',reference)}
async function remove(row:any){
 if(removing.value)return
 try{
  const current=await request('/admin/resources/'+encodeURIComponent(row.id))
  if(current.inUse){await load();ElMessage.warning('此文件已被引用，无法清理');return}
  await ElMessageBox.confirm(`将永久删除“${row.filename}”（${sizes(row.size)}）。未引用文件可能来自尚未保存的编辑，请确认已不再需要。`, '清理未引用文件',{type:'warning',confirmButtonText:'确认清理',cancelButtonText:'取消'})
  removing.value=row.id;const result=await send('/admin/resources/'+encodeURIComponent(row.id),{},'DELETE');if(selected.value?.id===row.id)close();await load();result.pendingRemoval?ElMessage.warning('资源已移出文件库，磁盘文件暂未清除'):ElMessage.success('文件已清理')
 }catch(e:any){if(e!=='cancel'&&e!=='close'){ElMessage.error(e.message||'清理失败');await load()}}finally{removing.value=''}
}
onMounted(load);onBeforeUnmount(()=>{disposed=true;previewRevision++});defineExpose({load})
</script>
<template>
 <section class="resource-management">
  <div class="resource-stats"><div v-for="stat in stats" :key="stat.label" class="resource-stat"><span class="stat-icon" :class="stat.tone"><component :is="stat.icon" :size="22" aria-hidden="true"/></span><div><span class="stat-label">{{stat.label}}</span><strong>{{stat.value}}</strong><small>{{stat.unit}}</small></div></div></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <form class="admin-filters" @submit.prevent="search">
   <label class="admin-filter-field resource-search"><span>文件名称</span><el-input v-model="filters.search" aria-label="文件名称" placeholder="搜索文件名称或唯一 ID" clearable @clear="search"><template #prefix><Search :size="16"/></template></el-input></label>
   <label class="admin-filter-field"><span>资源类型</span><el-select v-model="filters.kind" aria-label="资源类型" :empty-values="[null,undefined]" @change="search"><el-option label="全部类型" value=""/><el-option v-for="(name,key) in names" :key="key" :value="key" :label="name"/></el-select></label>
   <label class="admin-filter-field"><span>引用状态</span><el-select v-model="filters.usage" aria-label="引用状态" :empty-values="[null,undefined]" @change="search"><el-option label="全部状态" value=""/><el-option label="使用中" value="used"/><el-option label="未引用" value="unused"/></el-select></label>
   <div class="admin-filter-actions"><el-button type="primary" native-type="submit"><Search :size="16"/>查询</el-button><el-button @click="reset"><RotateCcw :size="16"/>重置</el-button></div>
  </form>
  <div class="resource-list-heading"><span>全部文件 <b>{{total}}</b></span><small>仅统计服务器资源，不包含外部链接</small></div>
  <el-table v-loading="busy" :data="rows" row-key="id" empty-text="暂无符合条件的资源">
   <el-table-column label="文件" min-width="260"><template #default="{row}"><button class="resource-file" @click="open(row)"><span class="file-icon" :class="row.kind"><component :is="icons[row.kind]" :size="22" aria-hidden="true"/></span><span><strong>{{row.filename}}</strong><small>{{extension(row)}}<span v-if="row.storage==='embedded'"> · 内嵌图片</span></small></span></button></template></el-table-column>
   <el-table-column label="唯一 ID" min-width="280"><template #default="{row}"><span class="resource-id">{{row.id}}</span></template></el-table-column><el-table-column label="类型" width="80"><template #default="{row}">{{names[row.kind]}}</template></el-table-column>
   <el-table-column label="文件大小" width="112"><template #default="{row}">{{sizes(row.size)}}</template></el-table-column>
   <el-table-column label="引用位置" min-width="260"><template #default="{row}"><div v-if="row.references.length" class="resource-reference"><button @click="locate(row.references[0])"><span>{{row.references[0].title}}</span><ArrowUpRight :size="14"/></button><small>{{ownerNames[row.references[0].kind]||'内容'}} · {{row.references[0].location}}</small><el-button v-if="row.references.length>1" link type="primary" @click="open(row)">查看全部 {{row.references.length}} 处引用</el-button></div><span v-else class="resource-muted">尚未关联已保存内容</span></template></el-table-column>
   <el-table-column label="引用状态" width="100"><template #default="{row}"><el-tag :type="row.inUse?'success':'info'" effect="light">{{row.inUse?'使用中':'未引用'}}</el-tag></template></el-table-column>
   <el-table-column label="上传时间" width="180"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column>
   <el-table-column label="操作" width="112" fixed="right"><template #default="{row}"><div class="row-actions"><el-tooltip content="预览与详情"><el-button link type="primary" aria-label="预览资源" @click="open(row)"><Eye :size="17"/></el-button></el-tooltip><el-tooltip :content="row.inUse?'使用中的文件不可清理':'清理未引用文件'"><span><el-button link type="danger" aria-label="清理资源" :disabled="row.inUse||!!removing" :loading="removing===row.id" @click="remove(row)"><Trash2 :size="17"/></el-button></span></el-tooltip></div></template></el-table-column>
  </el-table>
  <div class="pagination"><span>共 {{total}} 个文件</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next"/></div>
 </section>
 <el-drawer :model-value="visible" title="资源详情" size="min(800px,100vw)" class="resource-drawer" destroy-on-close @close="close">
  <template v-if="selected">
   <div class="resource-detail-heading"><span class="file-icon" :class="selected.kind"><component :is="icons[selected.kind]" :size="24"/></span><div><h2>{{selected.filename}}</h2><p>{{names[selected.kind]}} · {{sizes(selected.size)}}</p></div><el-tag :type="selected.inUse?'success':'info'">{{selected.inUse?'使用中':'未引用'}}</el-tag></div>
   <div class="resource-preview" v-loading="previewBusy">
    <el-alert v-if="previewError" :title="previewError" type="error" :closable="false" show-icon/>
    <template v-else-if="preview">
     <img v-if="selected.kind==='image'" :src="preview.url" :alt="selected.filename" @error="previewError='图片加载失败，请重新打开预览'"/>
     <video v-else-if="selected.kind==='video'" :src="preview.url" controls preload="metadata" @error="previewError='浏览器无法播放此视频，可下载原文件查看'"/>
     <div v-else-if="selected.kind==='audio'" class="audio-preview"><AudioLines :size="48" aria-hidden="true"/><audio :src="preview.url" controls preload="metadata" @error="previewError='浏览器无法播放此音频，可下载原文件查看'"/></div>
     <iframe v-else-if="selected.mime==='application/pdf'" :src="preview.url" title="PDF 讲义预览"/>
     <div v-else class="document-preview"><p>{{preview.notice||'此文件请下载后查看'}}</p><pre v-if="preview.text">{{preview.text}}</pre></div>
    </template>
   </div>
   <RecordIdentifier :id="selected.id" table="media_assets"/><div class="resource-detail-meta"><div><span>上传时间</span><strong>{{date(selected.createdAt)}}</strong></div><div><span>上传人</span><strong>{{selected.uploader||'未记录'}}</strong></div><div><span>存储方式</span><strong>{{selected.storage==='embedded'?'数据库内嵌图片':'服务器文件（相同内容共享存储）'}}</strong></div></div>
   <p v-if="!selected.createdAt" class="resource-muted">历史图片未记录原文件名和上传时间，此处按引用内容命名。</p>
   <section class="resource-locations"><h3>引用位置 <span>{{selected.references.length}}</span></h3><p v-if="!selected.references.length" class="resource-muted">此文件尚未被已保存内容引用，可能来自未完成的编辑或已替换的资源。</p><button v-for="(reference,index) in selected.references" :key="index" class="location-card" @click="locate(reference)"><span><small>{{ownerNames[reference.kind]||'内容'}} · {{reference.location}}{{reference.status==='draft'?' · 草稿':reference.status==='offline'?' · 已停用':''}}</small><strong>{{reference.title}}</strong><small v-if="reference.examName">{{reference.examName}}</small></span><ArrowUpRight :size="18"/></button></section>
  </template>
  <template #footer><div class="resource-detail-footer"><el-button v-if="selected&&!selected.inUse" type="danger" plain :loading="removing===selected.id" @click="remove(selected)"><Trash2 :size="16"/>清理文件</el-button><a v-if="preview?.downloadUrl" :href="preview.downloadUrl" class="resource-download" target="_blank" rel="noopener"><Download :size="16"/>下载原文件</a><el-button @click="close">关闭</el-button></div></template>
 </el-drawer>
</template>
<style scoped>
.resource-id{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px;line-height:1.6;color:var(--el-text-color-regular);overflow-wrap:anywhere;user-select:all}
.resource-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.resource-stat{border:1px solid var(--admin-border);border-radius:12px;padding:22px;display:flex;align-items:flex-start;gap:16px;background:var(--el-bg-color)}.stat-icon,.file-icon{display:grid;place-items:center;flex:none;width:44px;height:44px;border-radius:10px;background:var(--el-color-primary-light-9);color:var(--el-color-primary)}.stat-icon.green{background:var(--el-color-success-light-9);color:var(--el-color-success)}.stat-icon.amber{background:var(--el-color-warning-light-9);color:var(--el-color-warning)}.stat-icon.violet,.file-icon.video{background:#f0edff;color:#7254ca}.file-icon.audio{background:#e8f6f3;color:#208574}.file-icon.handout{background:#fff3e4;color:#a86418}.stat-label{display:block;font-size:13px;color:var(--el-text-color-regular)}.resource-stat strong{display:block;margin:8px 0 5px;font-size:28px;line-height:1.2;font-variant-numeric:tabular-nums;color:var(--admin-text)}.resource-stat small,.resource-muted{font-size:12px;color:var(--el-text-color-regular)}.resource-search{flex:2 1 260px}.resource-list-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:24px 0 16px;font-size:14px;font-weight:600}.resource-list-heading b,.resource-locations h3 span{font-size:12px;color:var(--el-text-color-regular);padding:3px 7px;border-radius:5px;background:var(--el-fill-color-light);margin-left:6px}.resource-list-heading small{font-weight:400;color:var(--el-text-color-regular)}.resource-file{display:flex;align-items:center;gap:12px;text-align:left;padding:8px 0;max-width:100%;border:0;background:none;cursor:pointer;color:var(--admin-text);font:inherit}.resource-file>span:last-child{min-width:0}.resource-file strong{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere;line-height:1.6;font-weight:500}.resource-file small{display:block;font-size:12px;color:var(--el-text-color-regular);margin-top:5px}.resource-file:hover strong,.resource-reference button:hover{color:var(--el-color-primary)}.resource-reference>button{border:0;background:none;font:inherit;text-align:left;cursor:pointer;padding:0;display:flex;align-items:center;gap:6px;max-width:100%;color:var(--admin-text)}.resource-reference>button>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.resource-reference svg{flex:none}.resource-reference small{display:block;color:var(--el-text-color-regular);font-size:12px;margin-top:4px}.resource-reference .el-button{height:26px;font-size:12px}.resource-detail-heading{display:flex;gap:14px;align-items:center;margin-bottom:24px}.resource-detail-heading>div{flex:1;min-width:0}.resource-detail-heading h2{font-size:18px;line-height:1.5;margin:0;overflow-wrap:anywhere}.resource-detail-heading p{margin:5px 0 0;color:var(--el-text-color-regular);font-size:13px}.resource-preview{min-height:260px;display:flex;justify-content:center;align-items:center;border:1px solid var(--admin-border);background:var(--el-fill-color-light);border-radius:10px;overflow:hidden}.resource-preview>img{display:block;max-width:100%;max-height:440px;object-fit:contain}.resource-preview>video{display:block;max-width:100%;max-height:440px;background:#142132}.resource-preview iframe{width:100%;height:520px;border:0;background:white}.audio-preview{display:flex;flex-direction:column;gap:30px;align-items:center;width:100%;padding:36px;color:var(--el-color-primary)}.audio-preview audio{width:100%}.document-preview{width:100%;max-height:520px;overflow:auto;padding:24px;box-sizing:border-box}.document-preview p{font-size:12px;color:var(--el-text-color-regular)}.document-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.8 inherit;color:var(--admin-text)}.resource-detail-meta{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:24px 0;border-bottom:1px solid var(--admin-border)}.resource-detail-meta span{display:block;color:var(--el-text-color-regular);font-size:12px;margin-bottom:8px}.resource-detail-meta strong{font-size:13px;font-weight:500}.resource-locations{margin-top:24px}.resource-locations h3{font-size:15px;margin:0 0 14px}.location-card{width:100%;display:flex;align-items:center;justify-content:space-between;gap:14px;text-align:left;background:var(--el-bg-color);border:1px solid var(--admin-border);border-radius:8px;padding:16px;margin:10px 0;cursor:pointer;color:var(--admin-text)}.location-card:hover{border-color:var(--el-color-primary);background:var(--el-color-primary-light-9)}.location-card strong{display:block;overflow-wrap:anywhere;font-size:14px;line-height:1.6;margin:5px 0}.location-card small{color:var(--el-text-color-regular);font-size:12px}.location-card svg{flex:none;color:var(--el-color-primary)}.resource-detail-footer{display:flex;justify-content:flex-end;align-items:center;gap:12px}.resource-detail-footer>.el-button:first-child{margin-right:auto}.resource-download{display:inline-flex;align-items:center;gap:6px;font-size:14px;color:var(--el-color-primary);text-decoration:none;min-height:40px}.resource-management :deep(.el-alert){margin-bottom:20px}@media(max-width:1200px){.resource-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.resource-stat{padding:14px;gap:10px}.resource-stat strong{font-size:22px}.resource-list-heading{align-items:flex-start;flex-direction:column;gap:8px}.resource-detail-meta{grid-template-columns:1fr}.resource-detail-heading{flex-wrap:wrap}.resource-detail-footer{flex-wrap:wrap}}
</style>
